export function escapeHtml(text: string): string {
  let out: string = "";
  for (let i = 0, i_finish = text.length; i < i_finish; ++i) {
    let c = text.charAt(i);
    let escaped: string;
    switch (c) {
      case "\"" :
        escaped = "&quot;";
        break;
      case "&" :
        escaped = "&amp;";
        break;
      case "'" :
        escaped = "&#39;";
        break;
      case "<" :
        escaped = "&lt;";
        break;
      case ">" :
        escaped = "&gt;";
        break;
      default:
        escaped = c;
    }
    out = out + escaped;
  }
  return out;
}

export function priorityLabel(p: TodoModel_priority): string {
  switch (p) {
    case "Low" :
      return "Low";
    case "Medium" :
      return "Med";
    case "High" :
      return "High";
  }
}

export function priorityClass(p: TodoModel_priority): string {
  switch (p) {
    case "Low" :
      return "prio-low";
    case "Medium" :
      return "prio-med";
    case "High" :
      return "prio-high";
  }
}

export function renderTodoItem(t: TodoModel_todo): string {
  let idStr = t.id.toString();
  let rowClass = t.done ? "todo-item is-done" : "todo-item";
  let checkMark = t.done ? "&#10003;" : "";
  let titleEsc = escapeHtml(t.title);
  let prioCls = priorityClass(t.priority);
  let prioLbl = priorityLabel(t.priority);
  return "<li class=\"" + rowClass + "\" data-id=\"" + idStr + "\"><button type=\"button\" class=\"check-btn\" title=\"Toggle complete\" onclick=\"post('/todos/" + idStr + "/toggle')\">" + checkMark + "</button><span class=\"todo-title\" ondblclick=\"editItem(" + idStr + ", this)\">" + titleEsc + "</span><button type=\"button\" class=\"prio-pill " + prioCls + "\" title=\"Click to cycle priority\" onclick=\"post('/todos/" + idStr + "/priority')\">" + prioLbl + "</button><button type=\"button\" class=\"icon-btn\" title=\"Edit title\" onclick=\"editFromBtn(" + idStr + ", this)\">&#9998;</button><button type=\"button\" class=\"icon-btn del-btn\" title=\"Delete\" onclick=\"del('/todos/" + idStr + "')\">&#10005;</button></li>";
}

export function renderFilterTab(label: string, count: number, target: TodoModel_filter, current: TodoModel_filter, query: string): string {
  let activeCls = target === current ? "tab is-active" : "tab";
  let fStr = TodoModel.filterToString(target);
  let qPart = query.trim().length > 0 ? "&amp;q=" + escapeHtml(query.trim()) : "";
  return "<a class=\"" + activeCls + "\" href=\"/?filter=" + fStr + qPart + "\">" + label + " <span class=\"tab-count\">" + count.toString() + "</span></a>";
}

